#include "password_auth.h"
#include <assert.h>
#include <string.h>
#include <stdio.h>
int main(void) { char out[65];
password_sha256_hex("",0,out); assert(!strcmp(out,"E3B0C44298FC1C149AFBF4C8996FB92427AE41E4649B934CA495991B7852B855"));
password_sha256_hex("abc",3,out); assert(!strcmp(out,"BA7816BF8F01CFEA414140DE5DAE2223B00361A396177A9CB410FF61F20015AD"));
password_sha256_hex("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",55,out); assert(!strcmp(out,"9F4390F8D30C2DD92EC9F095B65E2B9AE9B0A925A5258E241C9F1E910F734318"));
password_sha256_hex("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",56,out); assert(!strcmp(out,"B35439A4AC6F0948B6D6F9E3C6AF0F5F590CE20F1BDE7090EF7970686EC6738A"));
password_sha256_hex("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",64,out); assert(!strcmp(out,"FFE054FE7AE0CB6DC65C3AF9B61D5209F439851DB43D0BA5997337DF154668EB"));
password_sha256_hex("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",65,out); assert(!strcmp(out,"635361C48BB9EAB14198E76EA8AB7F1A41685D6AD62AA9146D301D4F17EB0AE0"));
password_sha256_hex("",1000,out); assert(!strcmp(out,"41EDECE42D63E8D9BF515A9BA6932E1C20CBC9F5A5D134645ADB5DB1B9737EA3"));
password_sha256_hex("中文密码",12,out); assert(!strcmp(out,"41D10E0253E1FE64E61EFF5E20E5EA632B3AA99257D17954894F56222F7EF0CD"));
assert(password_vendor_response("fixture-password","fixture-salt",out)); assert(!strcmp(out,"20BDBB3CF6843057DE843F378D0F5989CC2C3DB4F66708C85C12C90337322198"));
assert(!password_vendor_response("x","",out)); assert(!password_vendor_response(NULL,"salt",out));
puts("password auth tests passed"); return 0; }
